diff --git a/src/session-store.ts b/src/session-store.ts
index 77470f8..0bd4b40 100644
--- a/src/session-store.ts
+++ b/src/session-store.ts
@@ -1,4 +1,5 @@
 import { pool } from "./pool.ts";
+import { createHmac, randomUUID } from "crypto";

 export interface Session {
   id: string;
@@ -6,16 +7,59 @@ export interface Session {
   revokedAt: Date | null;
 }

+const SESSION_SECRET = process.env.SESSION_SECRET || "dev-secret-key";
+const revokedSessions = new Set<string>();
+
+const parseSessionToken = (token: string): { id: string; signature: string } | null => {
+  const parts = token.split(".");
+  if (parts.length !== 2) return null;
+  return { id: parts[0], signature: parts[1] };
+};
+
+const signSessionId = (id: string): string => {
+  const signature = createHmac("sha256", SESSION_SECRET).update(id).digest("hex").slice(0, 16);
+  return `${id}.${signature}`;
+};
+
+const verifySessionToken = (token: string): string | null => {
+  const parsed = parseSessionToken(token);
+  if (!parsed) return null;
+  const expectedSignature = createHmac("sha256", SESSION_SECRET)
+    .update(parsed.id)
+    .digest("hex")
+    .slice(0, 16);
+  if (parsed.signature !== expectedSignature) return null;
+  return parsed.id;
+};
+
 export const loadSession = async (id: string): Promise<Session | null> => {
+  const sessionId = verifySessionToken(id);
+  if (!sessionId) return null;
+
+  if (revokedSessions.has(sessionId)) return null;
+
   const result = await pool.query(
     "SELECT id, user_id, revoked_at FROM sessions WHERE id = $1",
-    [id],
+    [sessionId],
   );
   const row = result.rows[0];
-  if (row === undefined || row.revoked_at !== null) return null;
+  if (row === undefined || row.revoked_at !== null) {
+    revokedSessions.add(sessionId);
+    return null;
+  }
   return { id: row.id, userId: row.user_id, revokedAt: row.revoked_at };
 };

+export const validateSessionSignature = (token: string): string | null => {
+  const sessionId = verifySessionToken(token);
+  if (sessionId && revokedSessions.has(sessionId)) return null;
+  return sessionId;
+};
+
 export const revokeSession = async (id: string): Promise<void> => {
-  await pool.query("UPDATE sessions SET revoked_at = now() WHERE id = $1", [id]);
+  const sessionId = verifySessionToken(id);
+  if (sessionId) {
+    revokedSessions.add(sessionId);
+    await pool.query("UPDATE sessions SET revoked_at = now() WHERE id = $1", [sessionId]);
+  }
 };
